'use client'

import { useEffect, useRef, useState } from 'react'
import { toast } from 'sonner'
import QRCode from 'qrcode'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { Copy, Download } from 'lucide-react'

// Brand colors per CLAUDE.md — OK to use literally inside QR color config (not CSS styling)
const QR_DARK = '#0F0F0F'   // Onyx
const QR_LIGHT = '#F7F7F5'  // Bone

interface Props {
  publicUrl: string
  eventTitle: string
}

function slugSafeTitle(title: string): string {
  return title
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

export function EventShareCard({ publicUrl, eventTitle }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [absoluteUrl, setAbsoluteUrl] = useState(publicUrl)

  // Resolve absolute URL on mount (client-only)
  useEffect(() => {
    if (typeof window !== 'undefined') {
      setAbsoluteUrl(window.location.origin + publicUrl)
    }
  }, [publicUrl])

  // Render QR code into the display canvas (96×96)
  useEffect(() => {
    if (!canvasRef.current || !absoluteUrl) return
    QRCode.toCanvas(canvasRef.current, absoluteUrl, {
      width: 96,
      margin: 1,
      color: { dark: QR_DARK, light: QR_LIGHT },
    }).catch(() => {
      // Non-fatal — QR simply won't display if URL is malformed
    })
  }, [absoluteUrl])

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(absoluteUrl)
      toast.success('Link copied')
    } catch {
      toast.error('Could not copy link')
    }
  }

  function handleDownloadQr() {
    // Render at 1024×1024 into a hidden canvas, then trigger download
    const offscreen = document.createElement('canvas')
    QRCode.toCanvas(offscreen, absoluteUrl, {
      width: 1024,
      margin: 2,
      color: { dark: QR_DARK, light: QR_LIGHT },
    })
      .then(() => {
        const dataUrl = offscreen.toDataURL('image/png')
        const filename = `inkos-flash-${slugSafeTitle(eventTitle)}.png`
        const anchor = document.createElement('a')
        anchor.href = dataUrl
        anchor.download = filename
        anchor.click()
      })
      .catch(() => {
        toast.error('QR download failed')
      })
  }

  return (
    <Card className="shadow-soft border border-border/60 rounded-lg">
      <CardHeader className="pb-2 pt-4 px-4">
        <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
          Share
        </p>
      </CardHeader>
      <CardContent className="px-4 pb-4">
        <div className="grid grid-cols-1 sm:grid-cols-[1fr_auto] gap-4 items-start">
          {/* Left column — URL + action buttons */}
          <div className="space-y-3">
            <p className="text-xs font-mono text-foreground bg-muted px-2 py-1.5 rounded truncate select-all">
              {absoluteUrl}
            </p>
            <div className="flex gap-2 flex-wrap">
              <Button size="sm" onClick={handleCopy} className="h-8 text-xs gap-1.5">
                <Copy className="h-3.5 w-3.5" />
                Copy link
              </Button>
              <Button size="sm" variant="outline" onClick={handleDownloadQr} className="h-8 text-xs gap-1.5">
                <Download className="h-3.5 w-3.5" />
                Download QR
              </Button>
              {/* TODO: flyer PDF — requires worker job (generate-flash-flyer-pdf) */}
            </div>
          </div>

          {/* Right column — QR preview */}
          <div className="flex items-center justify-center sm:justify-end">
            <div className="rounded border border-border/60 p-1.5 bg-[--color-bone]">
              <canvas
                ref={canvasRef}
                width={96}
                height={96}
                className="block"
                aria-label={`QR code for ${eventTitle}`}
              />
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

