// ── Revenue breakdown for detail page Overview tab ────────────────────────────

export interface FlashEventRevenueBreakdown {
  lockedCents: number       // booked count × slot_price_cents
  collectedCents: number    // sum of deposit_cents for slots where deposit_paid = true
  outstandingCents: number  // locked − collected
  tipsCents: number         // flash_events.tips_collected_cents (added in migration 20260428100000)
  bookedCount: number
  noShowCount: number
}

export async function getFlashEventRevenueBreakdown(
  studioId: string,
  eventId: string
): Promise<FlashEventRevenueBreakdown> {
  const supabase = await createClient()

  // Verify ownership + fetch event pricing
  const { data: event, error: eventError } = await supabase
    .from('flash_events')
    .select('slot_price_cents, deposit_cents')
    .eq('studio_id', studioId)
    .eq('id', eventId)
    .maybeSingle()

  if (eventError || !event) {
    logger.error({ eventError, studioId, eventId }, 'getFlashEventRevenueBreakdown: event fetch failed')
    return { lockedCents: 0, collectedCents: 0, outstandingCents: 0, tipsCents: 0, bookedCount: 0, noShowCount: 0 }
  }

  // Fetch slots with booking deposit status
  const { data: slots, error: slotsError } = await supabase
    .from('flash_event_slots')
    .select('status, booking:bookings(deposit_paid)')
    .eq('flash_event_id', eventId)

  if (slotsError) {
    logger.error({ slotsError, eventId }, 'getFlashEventRevenueBreakdown: slots fetch failed')
    return { lockedCents: 0, collectedCents: 0, outstandingCents: 0, tipsCents: 0, bookedCount: 0, noShowCount: 0 }
  }

  let bookedCount = 0
  let noShowCount = 0
  let collectedCents = 0

  for (const slot of slots ?? []) {
    if (slot.status === 'booked') {
      bookedCount += 1
      // booking is returned as an object (single FK) or null
      const booking = slot.booking as { deposit_paid: boolean } | null
      if (booking?.deposit_paid) {
        collectedCents += event.deposit_cents
      }
    }
    // 'no_show' status added in migration 20260428100000; guard for pre-migration rows
    if ((slot.status as string) === 'no_show') {
      noShowCount += 1
    }
  }

  const lockedCents = bookedCount * event.slot_price_cents
  const outstandingCents = Math.max(0, lockedCents - collectedCents)

  // tips_collected_cents was added in migration 20260428100000 — types not yet regen'd
  // TODO: remove cast once `pnpm db:types` is run after migration applies
  const rawEvent = event as typeof event & { tips_collected_cents?: number | null }
  const tipsCents = rawEvent.tips_collected_cents ?? 0

  return {
    lockedCents,
    collectedCents,
    outstandingCents,
    tipsCents,
    bookedCount,
    noShowCount,
  }
}

