import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { formatCurrency } from '@/lib/utils'
import { cn } from '@/lib/utils'
import type { FlashEventRevenueBreakdown } from '@/lib/flash-events/queries'

interface Props {
  breakdown: FlashEventRevenueBreakdown | null
}

export function EventRevenuePanel({ breakdown }: Props) {
  if (!breakdown || breakdown.bookedCount === 0) return null

  const { lockedCents, collectedCents, outstandingCents, tipsCents } = breakdown

  return (
    <Card className="shadow-soft border border-border/60 rounded-lg">
      <CardHeader className="pb-2 pt-4 px-4">
        <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
          Revenue
        </p>
      </CardHeader>
      <CardContent className="px-4 pb-4 space-y-2.5">
        {/* Locked — single Rust 2px left accent (the hero KPI per viewport) */}
        <RevenueRow
          label="Locked"
          value={formatCurrency(lockedCents)}
          rustAccent
        />
        <RevenueRow
          label="Collected"
          value={formatCurrency(collectedCents)}
        />
        <RevenueRow
          label="Outstanding"
          value={formatCurrency(outstandingCents)}
          dimmed={outstandingCents === 0}
          warning={outstandingCents > 0}
        />
        <RevenueRow
          label="Tips"
          value={formatCurrency(tipsCents)}
          dimmed={tipsCents === 0}
        />
      </CardContent>
    </Card>
  )
}

interface RevenueRowProps {
  label: string
  value: string
  rustAccent?: boolean
  dimmed?: boolean
  warning?: boolean
}

function RevenueRow({ label, value, rustAccent, dimmed, warning }: RevenueRowProps) {
  return (
    <div
      className={cn(
        'flex items-center justify-between gap-4 pl-3',
        rustAccent && 'border-l-2 border-destructive'
      )}
    >
      <span className="text-sm text-muted-foreground shrink-0">{label}</span>
      <span
        className={cn(
          'text-sm font-medium tabular-nums',
          dimmed && 'text-muted-foreground',
          warning && 'text-warning',
          !dimmed && !warning && 'text-foreground'
        )}
      >
        {value}
      </span>
    </div>
  )
}

