// ── Overview tab ─────────────────────────────────────────────────────────────

interface OverviewTabProps {
  event: FlashEventDetail
  studioId: string
  publicUrl: string
  revenueBreakdown: FlashEventRevenueBreakdown | null
}

function OverviewTab({ event, studioId: _studioId, publicUrl, revenueBreakdown }: OverviewTabProps) {

{/* Revenue panel — hidden until first slot is booked */}
<EventRevenuePanel breakdown={revenueBreakdown} />

{/* Share card — only when published + public */}
{event.status === 'published' && event.public && (
  <EventShareCard publicUrl={publicUrl} eventTitle={event.title} />
)}

{event.description && (
  <Card>
    <CardContent className="pt-4 text-sm text-muted-foreground leading-relaxed">
      {event.description}
    </CardContent>
  </Card>
)}
